    public static void main(String[] args) throws ReflectiveOperationException {
        Class<?>[] some = { C000.class, C123.class, C599.class };
        long sum = 0;
        for (Class<?> c : some) {
            sum += c.getDeclaredMethods().length * 1000L + c.getDeclaredFields().length;
            Method m = c.getMethod(METHODS[(int) (sum % 24)], int.class);
            sum += (Integer) m.invoke(c.getDeclaredConstructor().newInstance(), 4);
            sum += c.getDeclaredField(FIELDS[(int) (sum % 6)]).getInt(c.getDeclaredConstructor().newInstance());
        }
        System.out.println(sum);
    }
